"""Adoption rule with intervals (DESCRIPTIVE, post-hoc, no verdict changed). For every judged run that stores per-detector AUROC intervals, classify each of the CORE 28 detectors against the 0.70 bar:
DET_PASS (95% lower bound >= 0.70), DET_FAIL (upper bound < 0.70), UNCERTAIN (interval contains 0.70), THIN (fewer than 50 held-out positives, as the run labelled it).
Then bound the detector count: lower = determinate passes, upper = determinate passes + uncertain, and say whether the 27-of-28 rule is decided by the data or not.
Core 28 = every fault in the run's table except R25, R26, K11, K12 (the four field-report faults reported alongside). usage: python docs/evidence/v10_adoption_intervals.py <kaggle_dir> <out.md> <out.json>"""
import csv, glob, json, os, sys

K, OUTM, OUTJ = sys.argv[1:4]; BAR = 0.70; NEED = 27; EXTRA = {'R25', 'R26', 'K11', 'K12'}
rows_out = []; md = ['# Adoption rule with intervals (descriptive; generated by `docs/evidence/v10_adoption_intervals.py`; no verdict is changed)', '',
                     f'Bar: held-out one-vs-rest AUROC >= {BAR}; adoption needs >= {NEED} of the core 28 detectors. `DET_PASS` = 95% lower bound >= {BAR}; `DET_FAIL` = upper bound < {BAR}; `UNCERTAIN` = the interval contains {BAR}; `THIN` = run flagged < 50 held-out positives.', '',
                     '| Run | Stored verdict | Stored detector count | DET_PASS | UNCERTAIN | DET_FAIL | THIN | Count range from the data | Does the data decide the 27 rule? | Uncertain detectors |', '|---|---|---|---|---|---|---|---|---|---|']
for d in sorted(glob.glob(os.path.join(K, 'judged_*'))):
    gp = os.path.join(d, 'detector_gates.csv'); vp = os.path.join(d, 'VERDICT.json')
    if not (os.path.exists(gp) and os.path.exists(vp)): continue
    rows = list(csv.DictReader(open(gp)))
    if not rows or 'ci_lo' not in rows[0] or 'ci_hi' not in rows[0]: continue
    V = json.load(open(vp)); core = [r for r in rows if r['fault'] not in EXTRA]
    if len(core) != 28: continue
    cl = collections = {}
    for r in core:
        if r['status'] == 'THIN': c = 'THIN'
        elif r['ci_lo'] == '' or r['ci_hi'] == '': c = 'UNCERTAIN'
        elif float(r['ci_lo']) >= BAR: c = 'DET_PASS'
        elif float(r['ci_hi']) < BAR: c = 'DET_FAIL'
        else: c = 'UNCERTAIN'
        cl[r['fault']] = c
    n = {k: sum(v == k for v in cl.values()) for k in ('DET_PASS', 'UNCERTAIN', 'DET_FAIL', 'THIN')}; lo, hi = n['DET_PASS'], n['DET_PASS'] + n['UNCERTAIN']
    decided = 'yes: adopted on any reading' if lo >= NEED else 'yes: not adopted on any reading' if hi < NEED else 'NO: depends on the uncertain detectors'
    unc = ', '.join(f"{f} ({float([r for r in core if r['fault'] == f][0]['auroc']):.2f})" for f, c in cl.items() if c == 'UNCERTAIN')
    md.append(f"| {os.path.basename(d)} | {V.get('verdict')} | {sum(r['status'] == 'PASS' for r in core)} | {n['DET_PASS']} | {n['UNCERTAIN']} | {n['DET_FAIL']} | {n['THIN']} | {lo} to {hi} | {decided} | {unc} |")
    rows_out.append(dict(run=os.path.basename(d), verdict=V.get('verdict'), stored_count=sum(r['status'] == 'PASS' for r in core), classes=cl, counts=n, lower=lo, upper=hi, decided=decided))
md += ['', 'Reading. A run whose count range straddles 27 has a verdict that rests on detectors whose intervals contain the bar: re-measuring the same construction could flip it. That is a statement about the measurement, not about the method, and it is why v6 (adopted) and v8 (not adopted) differ by one detector (C2) without a distinguishable change.']
open(OUTM, 'w').write('\n'.join(md) + '\n'); json.dump(rows_out, open(OUTJ, 'w'), indent=1); print('\n'.join(md))
